var GUIDE_GEN_KEY = "sp.guide.gen.max.v1";
function readMaxGen() {
try {
var v = localStorage.getItem(GUIDE_GEN_KEY);
if (v != null) { var n = parseInt(v, 10); if (!isNaN(n)) return n; }
} catch (e) {}
return -1;   
}
function writeMaxGen(n) {
try { localStorage.setItem(GUIDE_GEN_KEY, String(n)); } catch (e) {}
}


function findGuideInDOM() {
try {
var maxGen = readMaxGen();
var results = [];
var seenGen = maxGen;
var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null);
var node;
while ((node = walker.nextNode())) {
var txt = node.nodeValue || "";
if (txt.indexOf(GMARK) < 0) continue;
var list = findGuides(txt);      
if (!list || !list.length) continue;
var host = null;
var el = node.parentNode;
while (el && el !== document.body) {
try {
if (el.classList) {
if (el.classList.contains("reline") || el.classList.contains("bbscontent")) { host = el; break; }
if (el.classList.contains("retext") && !host) host = el;
}
} catch (e) {}
el = el.parentNode;
}
var h = host || node.parentNode;
for (var i = 0; i < list.length; i++) {
var g = list[i];
var gen = (g.gen | 0) || 0;

if (gen > seenGen) seenGen = gen;

if (maxGen >= 0 && gen < maxGen) continue;
results.push({ guide: g, host: h, t: (g.t | 0) || 0, gen: gen, ord: results.length });
}
}

if (maxGen < 0 && seenGen >= 0) writeMaxGen(seenGen);
if (!results.length) return null;

results.sort(function (a, b) {
return (b.gen - a.gen) || (b.t - a.t) || (b.ord - a.ord);
});

if (results[0].gen > maxGen) writeMaxGen(results[0].gen);
return results[0];
} catch (e) {}
return null;
}
